	private void timer1_Tick(object sender, EventArgs e)
	{
		//IL_00eb: Unknown result type (might be due to invalid IL or missing references)
		//IL_0101: Unknown result type (might be due to invalid IL or missing references)
		//IL_0270: Unknown result type (might be due to invalid IL or missing references)
		//IL_0286: Unknown result type (might be due to invalid IL or missing references)
		//IL_051e: Unknown result type (might be due to invalid IL or missing references)
		//IL_0534: Unknown result type (might be due to invalid IL or missing references)
		if (开启打印.Checked || checkBox28.Checked)
		{
			timer3.Enabled = true;
			timer1.Enabled = false;
		}
		else
		{
			if (!Parameters.IsAew100)
			{
				return;
			}
			Modbus.sp.DiscardOutBuffer();
			Modbus.sp.DiscardInBuffer();
			byte[] smessage = new byte[8];
			byte[] response = new byte[155];
			m.BuildSetMessage(1, ref smessage);
			try
			{
				Modbus.sp.Write(smessage, 0, smessage.Length);
				PortFlashWrite();
				Thread.Sleep(300);
				m.GetResponse(ref response);
				PortFlashRead();
			}
			catch (Exception ex)
			{
				timer1.Enabled = false;
				IsConnected = false;
				PortFalshInit();
				MessageBox.Show(ex.Message);
				MessageBox.Show(rm.GetString("请确定串口及地址设置"));
				return;
			}
			if (m.CheckResponse(response))
			{
				ShowMeterData(response);
				IsConnected = true;
			}
			else
			{
				IsConnected = false;
			}
			Thread.Sleep(20);
			if (((Control)textBox40).Text != "2310" && ((Control)textBox40).Text != "3521")
			{
				timer1.Enabled = false;
				Modbus.sp.DiscardOutBuffer();
				Modbus.sp.DiscardInBuffer();
				byte[] array = new byte[8];
				byte[] response2 = new byte[45];
				byte[] CRC = new byte[2];
				array[0] = Convert.ToByte(Parameters.Address);
				array[1] = 3;
				array[2] = 97;
				array[3] = 80;
				array[4] = 0;
				array[5] = 20;
				m.GetCRC(array, ref CRC);
				m.GetCRC(array, ref CRC);
				array[^2] = CRC[0];
				array[^1] = CRC[1];
				try
				{
					Modbus.sp.Write(array, 0, array.Length);
					PortFlashWrite();
					Thread.Sleep(20);
					m.GetResponse(ref response2);
					PortFlashRead();
				}
				catch (Exception ex)
				{
					timer1.Enabled = false;
					IsConnected = false;
					PortFalshInit();
					MessageBox.Show(ex.Message);
					MessageBox.Show(rm.GetString("请确定串口及地址设置"));
					return;
				}
				if (m.CheckResponse(response2))
				{
					if (Parameters.IsUse485)
					{
						timer1.Enabled = true;
					}
					if (response2[3] >= 8)
					{
						((SimpleShape)联网检验ovalShape1).FillColor = Color.Green;
					}
					else
					{
						((SimpleShape)联网检验ovalShape1).FillColor = Color.Red;
					}
					string text = "";
					byte[] array2 = new byte[15];
					byte[] array3 = new byte[20];
					string text2 = "状态：" + response2[3] + "\n信号：" + response2[4];
					for (int i = 0; i < 15; i++)
					{
						array2[i] = response2[5 + i];
					}
					string text3 = "IMEI号：" + Encoding.Default.GetString(array2);
					for (int i = 0; i < 20; i++)
					{
						array3[i] = response2[20 + i];
					}
					text = "ICCID：" + Encoding.Default.GetString(array3);
					((Control)联网状态).Text = text2 + "\n" + text3 + "\n" + text;
					IsConnected = true;
				}
			}
			Thread.Sleep(20);
			if (!CheckAddr())
			{
				return;
			}
			timer1.Enabled = false;
			Modbus.sp.DiscardOutBuffer();
			Modbus.sp.DiscardInBuffer();
			byte[] array4 = new byte[8];
			byte[] response3 = new byte[7];
			byte[] CRC2 = new byte[2];
			array4[0] = Convert.ToByte(Parameters.Address);
			array4[1] = 3;
			array4[2] = 1;
			array4[3] = 193;
			array4[4] = 0;
			array4[5] = 1;
			m.GetCRC(array4, ref CRC2);
			m.GetCRC(array4, ref CRC2);
			array4[^2] = CRC2[0];
			array4[^1] = CRC2[1];
			try
			{
				Modbus.sp.Write(array4, 0, array4.Length);
				PortFlashWrite();
				Thread.Sleep(20);
				m.GetResponse(ref response3);
				PortFlashRead();
			}
			catch (Exception ex)
			{
				timer1.Enabled = false;
				IsConnected = false;
				PortFalshInit();
				MessageBox.Show(ex.Message);
				MessageBox.Show(rm.GetString("请确定串口及地址设置"));
				return;
			}
			double num = 0.0;
			if (m.CheckResponse(response3))
			{
				if (Parameters.IsUse485)
				{
					timer1.Enabled = true;
				}
				num = (int)(ushort)((response3[3] << 8) | response3[4]);
				num = Convert.ToDouble(num) / 1000.0;
				((Control)textBoxIa).Text = Ia.ToString("f3");
				((Control)漏电流值).Text = num.ToString();
				IsConnected = true;
			}
		}
	}

	private void ShowVerID(byte[] res)
	{
		string text = "当前为";
		ushort num = (ushort)((res[3] << 8) | res[4]);
		switch (num)
		{
		case 797:
			text += "AEW100(SH)";
			break;
		case 696:
			text += "AEW100";
			break;
		case 711:
			text += "AEW110";
			break;
		case 798:
			text += "AEW110_L";
			break;
		}
		if (num == 797 || num == 696)
		{
			Parameters.IsAew100 = true;
			((Control)温度使能groupBox12).Visible = true;
			((Control)button3).Enabled = true;
			((Control)buttonCurrentScale).Enabled = true;
			((Control)buttonClearData).Enabled = true;
			((Control)buttonInit).Enabled = true;
			((Control)buttonCorrectTime).Enabled = true;
			((Control)buttonCorrect1).Enabled = true;
			((Control)buttonCorrect2).Enabled = true;
			timer1.Enabled = false;
			((Control)buttonReadType).Enabled = false;
			((Control)buttonSetType).Enabled = false;
			((Control)comboBoxCurrentScale).Enabled = true;
			((Control)comboBoxClearData).Enabled = true;
			((Control)comboBoxWorkType).Enabled = false;
			((Control)电流规格groupBox3).Visible = true;
			((Control)groupBox8).Visible = true;
			((Control)groupBox4).Visible = true;
			((Control)校准groupBox10).Visible = true;
			((Control)groupBox6).Visible = false;
		}
		else
		{
			Parameters.IsAew100 = false;
			((Control)button3).Enabled = false;
			((Control)buttonCurrentScale).Enabled = false;
			((Control)buttonClearData).Enabled = false;
			((Control)buttonInit).Enabled = false;
			((Control)buttonCorrectTime).Enabled = false;
			((Control)buttonCorrect1).Enabled = false;
			((Control)buttonCorrect2).Enabled = false;
			timer1.Enabled = false;
			((Control)comboBoxCurrentScale).Enabled = false;
			((Control)comboBoxClearData).Enabled = false;
			((Control)comboBoxWorkType).Enabled = true;
			((Control)buttonReadType).Enabled = true;
			((Control)buttonSetType).Enabled = true;
			((Control)电流规格groupBox3).Visible = false;
			((Control)groupBox4).Visible = false;
			((Control)校准groupBox10).Visible = false;
			((Control)groupBox6).Visible = true;
			((Control)groupBox8).Visible = false;
			((Control)温度使能groupBox12).Visible = false;
		}
		num = (ushort)((res[7] << 8) | res[8]);
		string text2 = text;
		text = text2 + "_V" + num / 100 + "." + (num % 100).ToString("00");
	}

