	private void SatrtRead()
	{
		Thread thread = new Thread(ReadByInr);
		thread.Start();
	}

	private void ReadByInr()
	{
		//IL_0095: Unknown result type (might be due to invalid IL or missing references)
		//IL_00ab: Unknown result type (might be due to invalid IL or missing references)
		//IL_014c: Unknown result type (might be due to invalid IL or missing references)
		//IL_0132: Unknown result type (might be due to invalid IL or missing references)
		bool flag = false;
		bool flag2 = false;
		int num = 0;
		while (!flag)
		{
			Modbus.sp.DiscardOutBuffer();
			Modbus.sp.DiscardInBuffer();
			byte[] smessage = new byte[8];
			byte[] response = new byte[155];
			m.BuildSetMessage(1, ref smessage);
			try
			{
				Modbus.sp.Write(smessage, 0, smessage.Length);
				PortFlashWrite();
				Thread.Sleep(10);
				m.GetResponse(ref response);
				PortFlashRead();
			}
			catch (Exception ex)
			{
				IsConnected = false;
				PortFalshInit();
				MessageBox.Show(ex.Message);
				MessageBox.Show(rm.GetString("请确定串口及地址设置"));
				return;
			}
			if (m.CheckResponse(response))
			{
				ShowMeterData(response);
				IsConnected = true;
				flag2 = true;
				flag = true;
				break;
			}
			num++;
			Thread.Sleep(500);
			if (num > 4)
			{
				flag = true;
				flag2 = false;
				break;
			}
		}
		if (flag2)
		{
			MessageBox.Show(rm.GetString("读取成功"));
		}
		else
		{
			MessageBox.Show(rm.GetString("读取失败"));
		}
	}

