	private void PortFlashWrite()
	{
		((SimpleShape)ovalShapeWrite).FillColor = Color.Red;
		((SimpleShape)ovalShapeRead).FillColor = Color.White;
	}

	private void PortFlashRead()
	{
		((SimpleShape)ovalShapeWrite).FillColor = Color.White;
		((SimpleShape)ovalShapeRead).FillColor = Color.Green;
	}

	private void PortFalshInit()
	{
		((SimpleShape)ovalShapeWrite).FillColor = Color.White;
		((SimpleShape)ovalShapeRead).FillColor = Color.White;
	}

