	private void buttonInit_Click(object sender, EventArgs e)
	{
		//IL_00b7: Unknown result type (might be due to invalid IL or missing references)
		//IL_00cd: Unknown result type (might be due to invalid IL or missing references)
		//IL_0196: Unknown result type (might be due to invalid IL or missing references)
		//IL_01ac: Unknown result type (might be due to invalid IL or missing references)
		//IL_00f8: Unknown result type (might be due to invalid IL or missing references)
		//IL_0225: Unknown result type (might be due to invalid IL or missing references)
		//IL_01fb: Unknown result type (might be due to invalid IL or missing references)
		if (!CheckAddr())
		{
			return;
		}
		timer1.Enabled = false;
		GetCurrentScale();
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] smessage = new byte[11];
		byte[] response = new byte[8];
		m.BuildSetMessage(26, ref smessage);
		try
		{
			Modbus.sp.Write(smessage, 0, smessage.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
			MessageBox.Show(rm.GetString("请确定串口及地址设置"));
			return;
		}
		if (!m.CheckResponse(response))
		{
			MessageBox.Show("校验错误，电流规格设置失败！");
		}
		Thread.Sleep(20);
		GetInitPara();
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] smessage2 = new byte[15];
		m.BuildSetMessage(5, ref smessage2);
		try
		{
			Modbus.sp.Write(smessage2, 0, smessage2.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
			MessageBox.Show(rm.GetString("请确定串口及地址设置"));
			return;
		}
		if (m.CheckResponse(response))
		{
			if (Parameters.IsUse485)
			{
				timer1.Enabled = true;
			}
			PortFalshInit();
			IsConnected = true;
			MessageBox.Show("初始化下发成功，请等待3s下发校准！");
		}
		else
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show("校验错误！");
		}
	}

	private void GetInitPara()
	{
		Parameters.InitPara.Un = Convert.ToInt16(((Control)comboBoxUn).Text + "0");
		if (((ListControl)comboBoxIb).SelectedIndex == 8)
		{
			Parameters.InitPara.Ib = 150;
		}
		else if (((ListControl)comboBoxIb).SelectedIndex != 0)
		{
			Parameters.InitPara.Ib = Convert.ToUInt16(((Control)comboBoxIb).Text + "00");
		}
		else
		{
			Parameters.InitPara.Ib = 100;
		}
		Parameters.InitPara.Ec = Convert.ToInt16(((Control)comboBoxEc).Text);
	}

