	private void GetDate()
	{
		dh = DateTime.Now;
		Parameters.CorrectTime.Second = (byte)dh.Second;
		Parameters.CorrectTime.Minute = (byte)dh.Minute;
		Parameters.CorrectTime.Hour = (byte)dh.Hour;
		Parameters.CorrectTime.Day = (byte)dh.Day;
		Parameters.CorrectTime.Month = (byte)dh.Month;
		if (dh.Year >= 2000)
		{
			Parameters.CorrectTime.Year = (byte)(dh.Year - 2000);
		}
		else
		{
			Parameters.CorrectTime.Year = (byte)(dh.Year - 1900);
		}
	}

	private bool CheckAddr()
	{
		//IL_0013: Unknown result type (might be due to invalid IL or missing references)
		//IL_0038: Unknown result type (might be due to invalid IL or missing references)
		if (Parameters.IsRightAddr != 1)
		{
			MessageBox.Show("请确认已输入正确的地址！");
			return false;
		}
		if (Parameters.IsPortOpen > 0)
		{
			return true;
		}
		MessageBox.Show("请先打开串口！");
		return false;
	}

	private void checkBoxUseInfrared_CheckedChanged(object sender, EventArgs e)
	{
		//IL_00dd: Unknown result type (might be due to invalid IL or missing references)
		timer1.Enabled = false;
		if (checkBoxUseInfrared.Checked)
		{
			Parameters.IsUse485 = false;
			((Control)textBox1).Text = "1";
			((Control)textBox1).Enabled = false;
			if (Modbus.sp.IsOpen)
			{
				m.close();
				Parameters.PortSet.PortBaud = "1200";
				m.Open();
			}
		}
		else
		{
			Parameters.IsUse485 = true;
			((Control)textBox1).Text = "1";
			((Control)textBox1).Enabled = true;
			if (Modbus.sp.IsOpen)
			{
				m.close();
				Parameters.PortSet.PortBaud = "9600";
				m.Open();
			}
		}
		MessageBox.Show("切换调试模式，请注意修改波特率并重新点击读取数据！");
	}

