	private void buttonSetCorrect_Click(object sender, EventArgs e)
	{
		//IL_00b5: Unknown result type (might be due to invalid IL or missing references)
		//IL_00cb: Unknown result type (might be due to invalid IL or missing references)
		//IL_0134: Unknown result type (might be due to invalid IL or missing references)
		//IL_011a: Unknown result type (might be due to invalid IL or missing references)
		if (!CheckAddr())
		{
			return;
		}
		timer1.Enabled = false;
		GetCorrectPara();
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] smessage = new byte[79];
		byte[] response = new byte[8];
		m.BuildSetMessage(33, ref smessage);
		try
		{
			Modbus.sp.Write(smessage, 0, smessage.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
			MessageBox.Show(rm.GetString("请确定串口及地址设置"));
			return;
		}
		if (m.CheckResponse(response))
		{
			if (Parameters.IsUse485)
			{
				timer1.Enabled = true;
			}
			IsConnected = true;
			MessageBox.Show(rm.GetString("设置成功"));
		}
		else
		{
			MessageBox.Show(rm.GetString("没有回复或校验错误"));
		}
	}

