		//IL_0136: Unknown result type (might be due to invalid IL or missing references)
		//IL_011c: Unknown result type (might be due to invalid IL or missing references)
		if (!CheckAddr())
		{
			return;
		}
		timer1.Enabled = false;
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] smessage = new byte[8];
		byte[] response = new byte[47];
		m.BuildSetMessage(36, ref smessage);
		try
		{
			Modbus.sp.Write(smessage, 0, smessage.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
			MessageBox.Show(rm.GetString("请确定串口及地址设置"));
			return;
		}
		if (m.CheckResponse(response))
		{
			if (Parameters.IsUse485)
			{
				timer1.Enabled = true;
			}
			ShowTimeSchedu(response, 2);
			IsConnected = true;
			MessageBox.Show(rm.GetString("读取成功"));
		}
		else
		{
			MessageBox.Show(rm.GetString("没有回复或校验错误"));
		}
	}

