	private void buttonSetSched2_Click(object sender, EventArgs e)
	{
		//IL_0138: Unknown result type (might be due to invalid IL or missing references)
		//IL_014e: Unknown result type (might be due to invalid IL or missing references)
		//IL_002f: Unknown result type (might be due to invalid IL or missing references)
		//IL_004d: Unknown result type (might be due to invalid IL or missing references)
		//IL_006b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0089: Unknown result type (might be due to invalid IL or missing references)
		//IL_01bb: Unknown result type (might be due to invalid IL or missing references)
		//IL_01a1: Unknown result type (might be due to invalid IL or missing references)
		int num = 0;
		if (!CheckAddr())
		{
			return;
		}
		switch (CheckTimeScheSet2())
		{
		case 2:
			MessageBox.Show("请确认输入的时段表不包含其他字符！");
			return;
		case 1:
			MessageBox.Show("请确认已输入时段表！");
			return;
		case 3:
			MessageBox.Show("请确认已输入正确的分钟！");
			return;
		case 4:
			MessageBox.Show("请确认已输入正确的时间！");
			return;
		}
		GetTimeSche2();
		timer1.Enabled = false;
		Modbus.sp.DiscardOutBuffer();
		Modbus.sp.DiscardInBuffer();
		byte[] smessage = new byte[51];
		byte[] response = new byte[8];
		m.BuildSetMessage(37, ref smessage);
		try
		{
			Modbus.sp.Write(smessage, 0, smessage.Length);
			PortFlashWrite();
			Thread.Sleep(20);
			m.GetResponse(ref response);
			PortFlashRead();
		}
		catch (Exception ex)
		{
			timer1.Enabled = false;
			IsConnected = false;
			PortFalshInit();
			MessageBox.Show(ex.Message);
			MessageBox.Show(rm.GetString("请确定串口及地址设置"));
			return;
		}
		if (m.CheckResponse(response))
		{
			if (Parameters.IsUse485)
			{
				timer1.Enabled = true;
			}
			IsConnected = true;
			MessageBox.Show(rm.GetString("设置成功"));
		}
		else
		{
			MessageBox.Show(rm.GetString("没有回复或校验错误"));
		}
	}

