	private static byte ConvertBCD(byte b)
	{
		byte b2 = (byte)(b / 10);
		byte b3 = (byte)(b % 10);
		return (byte)((b2 << 4) | b3);
	}

	public static byte ConvertBCDToInt(byte b)
	{
		byte b2 = (byte)((b >> 4) & 0xF);
		byte b3 = (byte)(b & 0xF);
		return (byte)(b2 * 10 + b3);
	}

