	private void button11_Click(object sender, EventArgs e)
	{
		//IL_00f5: Unknown result type (might be due to invalid IL or missing references)
		//IL_010b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0186: Unknown result type (might be due to invalid IL or missing references)
		//IL_016c: Unknown result type (might be due to invalid IL or missing references)
		Parameters.MessageType = 30;
		byte[] CRC = new byte[2];
		if (CheckAddr())
		{
			timer1.Enabled = false;
			Modbus.sp.DiscardOutBuffer();
			Modbus.sp.DiscardInBuffer();
			byte[] array = new byte[8];
			byte[] response = new byte[7];
			array[0] = Convert.ToByte(Parameters.Address);
			array[1] = 3;
			array[2] = 1;
			array[3] = 207;
			array[4] = 0;
			array[5] = 1;
			m.GetCRC(array, ref CRC);
			array[^2] = CRC[0];
			array[^1] = CRC[1];
			try
			{
				Modbus.sp.Write(array, 0, array.Length);
				PortFlashWrite();
				Thread.Sleep(20);
				m.GetResponse(ref response);
				PortFlashRead();
			}
			catch (Exception ex)
			{
				timer1.Enabled = false;
				IsConnected = false;
				PortFalshInit();
				MessageBox.Show(ex.Message);
				MessageBox.Show(rm.GetString("请确定串口及地址设置"));
				return;
			}
			if (m.CheckResponse(response))
			{
				((Control)剩余电流量程).Text = ((response[3] << 8) | response[4]).ToString();
				timer1.Enabled = true;
				IsConnected = true;
				MessageBox.Show(rm.GetString("读取成功"));
			}
			else
			{
				MessageBox.Show(rm.GetString("没有回复或校验错误"));
			}
		}
	}

