	private void ShowTHDALL(byte[] bb)
	{
		THDnum = (bb[3] << 8) | bb[4];
		THDnum = Convert.ToDouble(THDnum) / 100.0;
		((Control)谐波电压A).Text = THDnum.ToString("f2");
		THDnum = (bb[5] << 8) | bb[6];
		THDnum = Convert.ToDouble(THDnum) / 100.0;
		((Control)谐波电压B).Text = THDnum.ToString("f2");
		THDnum = (bb[7] << 8) | bb[8];
		THDnum = Convert.ToDouble(THDnum) / 100.0;
		((Control)谐波电压C).Text = THDnum.ToString("f2");
		THDnum = (bb[9] << 8) | bb[10];
		THDnum = Convert.ToDouble(THDnum) / 100.0;
		((Control)谐波电流A).Text = THDnum.ToString("f2");
		THDnum = (bb[11] << 8) | bb[12];
		THDnum = Convert.ToDouble(THDnum) / 100.0;
		((Control)谐波电流B).Text = THDnum.ToString("f2");
		THDnum = (bb[13] << 8) | bb[14];
		THDnum = Convert.ToDouble(THDnum) / 100.0;
		((Control)谐波电流C).Text = THDnum.ToString("f2");
	}

