	private void timer3_Tick(object sender, EventArgs e)
	{
		if (!开启打印.Checked && !checkBox28.Checked)
		{
			timer1.Enabled = true;
			timer3.Enabled = false;
			return;
		}
		int num = 0;
		string text = "";
		byte[] array = new byte[1000];
		if (Modbus.sp.BytesToRead != 0)
		{
			num = Modbus.sp.BytesToRead;
			int num2 = Modbus.sp.Read(array, 0, num);
			for (int i = 0; i < num; i++)
			{
				text += Encoding.Default.GetString(array);
			}
			((Control)打印信息).Text = ((Control)打印信息).Text + text;
			((Control)richTextBox2).Text = ((Control)richTextBox2).Text + text;
			num2 = ((Control)打印信息).Text.Length;
			num = ((Control)richTextBox2).Text.Length;
			if (num2 > 4096)
			{
				((Control)打印信息).Text = "";
			}
			if (num > 4096)
			{
				((Control)richTextBox2).Text = "";
			}
			((Control)联网状态).Text = "IMEI:" + MidStrEx(((Control)打印信息).Text, "MAC:", "+");
		}
	}

	public static string MidStrEx(string sourse, string startstr, string endstr)
	{
		//IL_006a: Unknown result type (might be due to invalid IL or missing references)
		string result = string.Empty;
		try
		{
			int num = sourse.IndexOf(startstr);
			if (num == -1)
			{
				return result;
			}
			string text = sourse.Substring(num + startstr.Length);
			int num2 = text.IndexOf(endstr);
			if (num2 == -1)
			{
				return result;
			}
			result = text.Remove(num2);
		}
		catch (Exception ex)
		{
			MessageBox.Show("MidStrEx Err:" + ex.Message);
		}
		return result;
	}

