	private static string createToken(string HostName, string DeviceName, string key)
	{
		string str = HostName + "/devices/" + DeviceName;
		string text = HttpUtility.UrlEncode(str);
		string text2 = "2259886725";
		string s = text + "\n" + text2;
		byte[] bytes = Encoding.UTF8.GetBytes(s);
		HMACSHA256 hMACSHA = new HMACSHA256(Convert.FromBase64String(key));
		string str2 = Convert.ToBase64String(hMACSHA.ComputeHash(bytes));
		return HttpUtility.UrlEncode(str2);
	}

