		array[3] = 128;
		array[4] = 0;
		array[5] = 4;
		array[6] = 8;
		string text = Convert.ToString(((Control)textBox223).Text);
		if (text.Length < 16)
		{
			MessageBox.Show("位数错误，SN为16位！");
			return;
		}
		int num = 7;
		int num2 = 0;
		int num3 = num;
		while (num2 < text.Length)
